action.command:
cat > /tmp/scan.mjs <<'EOF'
import fs from "fs";
const s = fs.readFileSync("/opt/node/lib/node_modules/pnpm/dist/pnpm.mjs","utf8");
const lines = s.split("\n");
let count=0;
for (let n=0;n<lines.length && count<80;n++){
  const m = lines[n];
  if (m.includes("minimumReleaseAge")) { console.log(n, m.trim().slice(0,140)); count++; }
}
EOF
node /tmp/scan.mjs

